package io.github.diodeme.ji.session;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.model.CommandJournal;
import io.github.diodeme.ji.session.model.CompletionGuard;
import io.github.diodeme.ji.session.model.Recovery;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.Executors;
import org.junit.jupiter.api.Test;

final class CanonicalSessionStateTest {
    @Test
    void sessionDoesNotMirrorRunExecutionStatus() {
        assertThrows(IllegalArgumentException.class, () -> CanonicalSessionState.SessionStatus.valueOf("ACTIVE"));
        var active = activeModelState();
        var paused = Recovery.pauseAfterRestart(active);
        assertEquals(CanonicalSessionState.SessionStatus.AVAILABLE, paused.status());
        assertEquals(CanonicalSessionState.RunStatus.PAUSED, paused.activeRun().orElseThrow().status());
    }

    @Test
    void rejectsRunningRunWithPausedTurn() {
        var paused = Recovery.pauseAfterRestart(activeModelState());
        var run = paused.activeRun().orElseThrow();
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.Run(
                run.id(), run.sessionId(), CanonicalSessionState.RunStatus.RUNNING,
                Optional.empty(), Optional.empty(), run.revision(), run.turns(), run.startedAt(), Optional.empty()));
    }

    @Test
    void turnToolAndCompactionTransitionsAdvanceOwnRevisions() {
        var streaming = activeModelState().activeRun().orElseThrow().turns().getFirst();
        var completedAttempt = streaming.attempts().getFirst().finish(
                CanonicalSessionState.AttemptOutcome.SUCCEEDED, 0);
        var waiting = streaming.transition(
                CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS,
                Optional.empty(), Optional.empty(), List.of(completedAttempt), List.of(), List.of(), 0);
        assertEquals(1, waiting.revision());
        assertThrows(IllegalStateException.class, () -> waiting.transition(
                CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                Optional.empty(), Optional.empty(), waiting.attempts(), waiting.tools(), waiting.permissions(), 1));

        var runningTool = activeToolState(CanonicalSessionState.ToolRetryContract.READ_ONLY, Optional.empty())
                .activeRun().orElseThrow().turns().getFirst().tools().getFirst();
        var pausedAttempt = runningTool.attempts().getLast().pause(0);
        var pausedTool = runningTool.transition(
                CanonicalSessionState.ToolStatus.PAUSED, Optional.empty(), List.of(pausedAttempt), 0);
        assertEquals(1, pausedTool.revision());
        assertThrows(IllegalStateException.class, () -> pausedTool.transition(
                CanonicalSessionState.ToolStatus.PREPARED, Optional.empty(), pausedTool.attempts(), 1));

        var compactionId = new CanonicalSessionState.CompactionId("compaction-1");
        var compactionAttempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId("compaction-attempt-1"), compactionId.value(), 1,
                CanonicalSessionState.AttemptStep.COMPACTION, CanonicalSessionState.AttemptStatus.RUNNING,
                Optional.empty(), 0, "entry-summary-1");
        var compaction = new CanonicalSessionState.Compaction(
                compactionId, new CanonicalSessionState.SessionId("session-1"),
                CanonicalSessionState.CompactionStatus.RUNNING, Optional.empty(), 0,
                List.of(compactionAttempt), Optional.empty());
        var pausedCompaction = compaction.transition(
                CanonicalSessionState.CompactionStatus.PAUSED, Optional.empty(),
                List.of(compactionAttempt.pause(0)), Optional.empty(), 0);
        assertEquals(1, pausedCompaction.revision());
        assertThrows(IllegalStateException.class, () -> pausedCompaction.transition(
                CanonicalSessionState.CompactionStatus.PAUSED, Optional.empty(),
                pausedCompaction.attempts(), Optional.empty(), 1));
    }

    @Test
    void everyLifecycleOwnsStatusOutcomeRevisionAndClosedTransitions() {
        var session = idleState();
        var trashed = session.transition(CanonicalSessionState.SessionStatus.TRASHED, Optional.empty(), 0);
        assertEquals(1, trashed.revision());
        var tombstoned = trashed.transition(
                CanonicalSessionState.SessionStatus.TOMBSTONED,
                Optional.of(CanonicalSessionState.SessionOutcome.DELETED), 1);
        assertEquals(Optional.of(CanonicalSessionState.SessionOutcome.DELETED), tombstoned.outcome());
        assertThrows(IllegalStateException.class,
                () -> trashed.transition(CanonicalSessionState.SessionStatus.TRASHED, Optional.empty(), 1));

        var permission = new CanonicalSessionState.Permission(
                new CanonicalSessionState.PermissionId("permission-1"), session.sessionId(),
                new CanonicalSessionState.ToolExecutionId("tool-1"),
                CanonicalSessionState.PermissionStatus.PENDING, Optional.empty(), 0, Instant.EPOCH.plusSeconds(10));
        var allowed = permission.resolve(CanonicalSessionState.PermissionOutcome.ALLOWED, 0, Instant.EPOCH);
        assertEquals(1, allowed.revision());
        assertEquals(Optional.of(CanonicalSessionState.PermissionOutcome.ALLOWED), allowed.outcome());
        assertThrows(IllegalStateException.class,
                () -> allowed.resolve(CanonicalSessionState.PermissionOutcome.DENIED, 1, Instant.EPOCH));

        var attempt = activeModelState().activeRun().orElseThrow().turns().getFirst().attempts().getFirst();
        var succeeded = attempt.finish(CanonicalSessionState.AttemptOutcome.SUCCEEDED, 0);
        assertEquals(1, succeeded.revision());
        assertThrows(IllegalStateException.class,
                () -> attempt.finish(CanonicalSessionState.AttemptOutcome.SUPERSEDED, 0));
    }

    @Test
    void terminalTurnRejectsAnUnfinishedModelAttempt() {
        var active = activeModelState().activeRun().orElseThrow().turns().getFirst();
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.Turn(
                active.id(), active.runId(), active.number(), CanonicalSessionState.TurnStatus.TERMINAL,
                Optional.of(CanonicalSessionState.TurnOutcome.COMPLETED), Optional.empty(),
                active.revision(), active.attempts(), active.tools(), active.permissions()));
    }

    @Test
    void pausedRunRequiresAPausedCurrentTurn() {
        var sessionId = new CanonicalSessionState.SessionId("session-1");
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.Run(
                new CanonicalSessionState.RunId("run-1"), sessionId, CanonicalSessionState.RunStatus.PAUSED,
                Optional.empty(), Optional.of(CanonicalSessionState.RunPauseReason.HOST_RESTART),
                0, List.of(), Instant.EPOCH, Optional.empty()));
    }

    @Test
    void permissionAndAttemptOwnershipCannotCrossAggregateBoundaries() {
        var turn = activeToolState(CanonicalSessionState.ToolRetryContract.READ_ONLY, Optional.empty())
                .activeRun().orElseThrow().turns().getFirst();
        var tool = turn.tools().getFirst();
        var foreignPermission = new CanonicalSessionState.Permission(
                new CanonicalSessionState.PermissionId("permission-1"),
                new CanonicalSessionState.SessionId("session-2"), tool.id(),
                CanonicalSessionState.PermissionStatus.RESOLVED,
                Optional.of(CanonicalSessionState.PermissionOutcome.ALLOWED), 1, Instant.EPOCH);
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.Turn(
                turn.id(), turn.runId(), turn.number(), turn.status(), turn.outcome(), turn.pausedFrom(),
                turn.revision(), turn.attempts(), turn.tools(), List.of(foreignPermission)));

        var prior = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId("tool-attempt-1"), tool.id().value(), 1,
                CanonicalSessionState.AttemptStep.TOOL, CanonicalSessionState.AttemptStatus.TERMINAL,
                Optional.of(CanonicalSessionState.AttemptOutcome.SUPERSEDED), 2, "wrong-result-entry");
        var current = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId("tool-attempt-2"), tool.id().value(), 2,
                CanonicalSessionState.AttemptStep.TOOL, CanonicalSessionState.AttemptStatus.RUNNING,
                Optional.empty(), 0, tool.resultEntryId());
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.ToolExecution(
                tool.id(), tool.sessionId(), tool.runId(), tool.turnId(), tool.toolCallId(), tool.toolName(),
                tool.resultEntryId(), List.of(prior, current), tool.retryContract(),
                tool.resumeToken(), tool.status(), tool.outcome(), tool.revision()));
    }

    @Test
    void aggregateRejectsToolFromAnotherSession() {
        var state = activeToolState(CanonicalSessionState.ToolRetryContract.READ_ONLY, Optional.empty());
        var run = state.activeRun().orElseThrow();
        var turn = run.turns().getFirst();
        var tool = turn.tools().getFirst();
        var foreignTool = new CanonicalSessionState.ToolExecution(
                tool.id(), new CanonicalSessionState.SessionId("session-2"), run.id(), turn.id(),
                tool.toolCallId(), tool.toolName(), tool.resultEntryId(), tool.attempts(), tool.retryContract(),
                tool.resumeToken(), tool.status(), tool.outcome(), tool.revision());
        var foreignTurn = new CanonicalSessionState.Turn(
                turn.id(), run.id(), turn.number(), turn.status(), turn.outcome(), turn.pausedFrom(),
                turn.revision(), turn.attempts(), List.of(foreignTool), turn.permissions());
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.Run(
                run.id(), run.sessionId(), run.status(), run.outcome(), run.pauseReason(), run.revision(),
                List.of(foreignTurn), run.startedAt(), run.endedAt()));
    }

    @Test
    void pausedTurnRejectsRunningAttemptAndTool() {
        var modelTurn = activeModelState().activeRun().orElseThrow().turns().getFirst();
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.Turn(
                modelTurn.id(), modelTurn.runId(), modelTurn.number(), CanonicalSessionState.TurnStatus.PAUSED,
                Optional.empty(), Optional.of(CanonicalSessionState.TurnPhase.MODEL_STREAMING), modelTurn.revision(),
                modelTurn.attempts(), modelTurn.tools(), modelTurn.permissions()));

        var toolTurn = activeToolState(CanonicalSessionState.ToolRetryContract.READ_ONLY, Optional.empty())
                .activeRun().orElseThrow().turns().getFirst();
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState.Turn(
                toolTurn.id(), toolTurn.runId(), toolTurn.number(), CanonicalSessionState.TurnStatus.PAUSED,
                Optional.empty(), Optional.of(CanonicalSessionState.TurnPhase.WAITING_FOR_TOOLS), toolTurn.revision(),
                toolTurn.attempts(), toolTurn.tools(), toolTurn.permissions()));
    }

    @Test
    void sessionHasTerminalOutcomeAndClosedTransition() {
        assertEquals(Optional.class, java.util.Arrays.stream(CanonicalSessionState.class.getRecordComponents())
                .filter(component -> component.getName().equals("outcome"))
                .findFirst().orElseThrow().getType());
        assertEquals(CanonicalSessionState.class, assertDoesNotThrow(() -> CanonicalSessionState.class.getMethod(
                "transition", CanonicalSessionState.SessionStatus.class, Optional.class, long.class)).getReturnType());

        var activeCompaction = activeCompactionState();
        assertThrows(IllegalArgumentException.class, () -> new CanonicalSessionState(
                activeCompaction.sessionId(), CanonicalSessionState.SessionStatus.TRASHED, Optional.empty(),
                activeCompaction.revision(), Optional.empty(), List.of(), activeCompaction.compactions()));
    }

    @Test
    void restartPausesAndResumesCompactionWithoutActiveRun() {
        var active = activeCompactionState();
        var paused = Recovery.pauseAfterRestart(active);
        var pausedCompaction = paused.compactions().getFirst();
        assertEquals(CanonicalSessionState.CompactionStatus.PAUSED, pausedCompaction.status());
        assertEquals(active.compactions().getFirst().id(), pausedCompaction.id());
        assertEquals(CanonicalSessionState.AttemptStatus.PAUSED, pausedCompaction.attempts().getFirst().status());

        var resumed = Recovery.resumeCompaction(
                paused, pausedCompaction.id(), new CanonicalSessionState.AttemptId("compaction-attempt-2"),
                "entry-summary-2", pausedCompaction.revision());
        var compaction = resumed.compactions().getFirst();
        assertEquals(CanonicalSessionState.CompactionStatus.RUNNING, compaction.status());
        assertEquals(pausedCompaction.id(), compaction.id());
        assertEquals(CanonicalSessionState.AttemptOutcome.SUPERSEDED,
                compaction.attempts().getFirst().outcome().orElseThrow());
        assertEquals(2, compaction.attempts().getLast().number());
        assertEquals("entry-summary-2", compaction.attempts().getLast().resultEntryId());
        assertThrows(IllegalStateException.class, () -> Recovery.resumeCompaction(
                paused, pausedCompaction.id(), new CanonicalSessionState.AttemptId("compaction-attempt-stale"),
                "entry-summary-stale", pausedCompaction.revision() - 1));
    }

    @Test
    void recoveryPreservesRunAndSupersedesModelAttempt() {
        CanonicalSessionState state = activeModelState();
        CanonicalSessionState paused = Recovery.pauseAfterRestart(state);
        CanonicalSessionState resumed = Recovery.resume(
                paused, new CanonicalSessionState.AttemptId("attempt-2"), "entry-assistant-2");

        assertSame(paused, Recovery.pauseAfterRestart(paused));
        assertEquals(state.activeRun().orElseThrow().id(), resumed.activeRun().orElseThrow().id());
        assertEquals(2, resumed.activeRun().orElseThrow().revision());
        var attempts = resumed.activeRun().orElseThrow().turns().getFirst().attempts();
        assertEquals(CanonicalSessionState.AttemptStatus.TERMINAL, attempts.getFirst().status());
        assertEquals(Optional.of(CanonicalSessionState.AttemptOutcome.SUPERSEDED), attempts.getFirst().outcome());
        assertEquals(2, attempts.getLast().number());
        assertEquals("entry-assistant-2", attempts.getLast().resultEntryId());
    }

    @Test
    void nonRetryableToolCannotCreateARecoveryAttempt() {
        var paused = Recovery.pauseAfterRestart(activeToolState(CanonicalSessionState.ToolRetryContract.NON_RETRYABLE, Optional.empty()));
        assertThrows(IllegalStateException.class, () -> Recovery.resume(
                paused, new CanonicalSessionState.AttemptId("tool-attempt-2"), "ignored"));
        var tool = paused.activeRun().orElseThrow().turns().getFirst().tools().getFirst();
        assertEquals(1, tool.attempts().getLast().number());
    }

    @Test
    void resumableToolRequiresDurableResumeToken() {
        var withoutToken = [REDACTED_CREDENTIAL] Optional.empty()));
        assertThrows(IllegalStateException.class, () -> Recovery.resume(
                withoutToken, new CanonicalSessionState.AttemptId("tool-attempt-2"), "ignored"));

        var withToken = [REDACTED_CREDENTIAL]
                CanonicalSessionState.ToolRetryContract.RESUMABLE, Optional.of("checkpoint-1")));
        var resumed = Recovery.resume(withToken, new CanonicalSessionState.AttemptId("tool-attempt-2"), "ignored");
        var tool = resumed.activeRun().orElseThrow().turns().getFirst().tools().getFirst();
        assertEquals(CanonicalSessionState.ToolStatus.RUNNING, tool.status());
        assertEquals(2, tool.attempts().getLast().number());
        assertEquals(2, tool.revision());
    }

    @Test
    void duplicateCommandReturnsOriginalResultAndJournalRestoresWatermark() {
        var sessionId = new CanonicalSessionState.SessionId("session-1");
        CommandJournal journal = new CommandJournal(sessionId);
        var first = journal.accept("command-1", CommandJournal.utf8("same"), "result-1");
        var duplicate = journal.accept("command-1", CommandJournal.utf8("same"), "result-ignored");
        assertSame(first, duplicate);
        var restored = new CommandJournal(sessionId, journal.watermark().lastAcceptedSeq(), journal.entries());
        assertEquals(2, restored.accept("command-2", CommandJournal.utf8("next"), "result-2").acceptedSeq());
        assertThrows(CommandJournal.CommandPayloadConflictException.class,
                () -> restored.accept("command-1", CommandJournal.utf8("different"), "result-3"));
    }

    @Test
    void rejectedCommandDoesNotConsumeAcceptedSequence() {
        CommandJournal journal = new CommandJournal(new CanonicalSessionState.SessionId("session-1"));
        assertThrows(IllegalArgumentException.class,
                () -> journal.accept(" ", CommandJournal.utf8("invalid"), "result-invalid"));
        assertEquals(1, journal.accept("command-1", CommandJournal.utf8("valid"), "result-1").acceptedSeq());
    }

    @Test
    void concurrentDuplicateCommandHasOneAcceptedSequence() throws Exception {
        CommandJournal journal = new CommandJournal(new CanonicalSessionState.SessionId("session-1"));
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            var tasks = java.util.stream.IntStream.range(0, 32)
                    .<java.util.concurrent.Callable<Long>>mapToObj(index -> () ->
                            journal.accept("command-1", CommandJournal.utf8("same"), "result-1").acceptedSeq())
                    .toList();
            var results = executor.invokeAll(tasks);
            assertEquals(1, results.stream().map(future -> {
                try { return future.get(); }
                catch (Exception exception) { throw new AssertionError(exception); }
            }).distinct().count());
        }
    }

    @Test
    void rejectsLateEffectCompletion() {
        var expected = new CompletionGuard.OperationIdentity("tool-1", 4);
        var stale = new CompletionGuard.OperationIdentity("tool-1", 3);
        assertThrows(CompletionGuard.StaleCompletionException.class,
                () -> CompletionGuard.requireCurrent(expected, stale));
    }

    private static CanonicalSessionState idleState() {
        return new CanonicalSessionState(
                new CanonicalSessionState.SessionId("session-1"),
                CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 0,
                Optional.empty(), List.of(), List.of());
    }

    private static CanonicalSessionState activeCompactionState() {
        var sessionId = new CanonicalSessionState.SessionId("session-1");
        var compactionId = new CanonicalSessionState.CompactionId("compaction-1");
        var attempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId("compaction-attempt-1"), compactionId.value(), 1,
                CanonicalSessionState.AttemptStep.COMPACTION, CanonicalSessionState.AttemptStatus.RUNNING,
                Optional.empty(), 0, "entry-summary-1");
        var compaction = new CanonicalSessionState.Compaction(
                compactionId, sessionId, CanonicalSessionState.CompactionStatus.RUNNING,
                Optional.empty(), 0, List.of(attempt), Optional.empty());
        return new CanonicalSessionState(
                sessionId, CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 1,
                Optional.empty(), List.of(), List.of(compaction));
    }

    private static CanonicalSessionState activeModelState() {
        var sessionId = new CanonicalSessionState.SessionId("session-1");
        var runId = new CanonicalSessionState.RunId("run-1");
        var turnId = new CanonicalSessionState.TurnId("turn-1");
        var attempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId("attempt-1"), turnId.value(), 1,
                CanonicalSessionState.AttemptStep.ASSISTANT, CanonicalSessionState.AttemptStatus.RUNNING,
                Optional.empty(), 0, "entry-assistant-1");
        var turn = new CanonicalSessionState.Turn(
                turnId, runId, 1, CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                Optional.empty(), Optional.empty(), 0, List.of(attempt), List.of(), List.of());
        var run = new CanonicalSessionState.Run(
                runId, sessionId, CanonicalSessionState.RunStatus.RUNNING,
                Optional.empty(), Optional.empty(), 0, List.of(turn), Instant.EPOCH, Optional.empty());
        return new CanonicalSessionState(
                sessionId, CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 1,
                Optional.of(run), List.of(), List.of());
    }

    private static CanonicalSessionState activeToolState(
            CanonicalSessionState.ToolRetryContract retryContract, Optional<String> resumeToken) {
        var sessionId = new CanonicalSessionState.SessionId("session-1");
        var runId = new CanonicalSessionState.RunId("run-1");
        var turnId = new CanonicalSessionState.TurnId("turn-1");
        var modelAttempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId("attempt-model-1"), turnId.value(), 1,
                CanonicalSessionState.AttemptStep.ASSISTANT, CanonicalSessionState.AttemptStatus.TERMINAL,
                Optional.of(CanonicalSessionState.AttemptOutcome.SUCCEEDED), 1, "entry-assistant-1");
        var toolId = new CanonicalSessionState.ToolExecutionId("tool-1");
        var toolAttempt = new CanonicalSessionState.Attempt(
                new CanonicalSessionState.AttemptId("tool-attempt-1"), toolId.value(), 1,
                CanonicalSessionState.AttemptStep.TOOL, CanonicalSessionState.AttemptStatus.RUNNING,
                Optional.empty(), 0, "entry-tool-result-1");
        var tool = new CanonicalSessionState.ToolExecution(
                toolId, sessionId, runId, turnId, "tool-call-1", "write_file", "entry-tool-result-1",
                List.of(toolAttempt), retryContract, resumeToken, CanonicalSessionState.ToolStatus.RUNNING,
                Optional.empty(), 0);
        var turn = new CanonicalSessionState.Turn(
                turnId, runId, 1, CanonicalSessionState.TurnStatus.WAITING_FOR_TOOLS,
                Optional.empty(), Optional.empty(), 0, List.of(modelAttempt), List.of(tool), List.of());
        var run = new CanonicalSessionState.Run(
                runId, sessionId, CanonicalSessionState.RunStatus.RUNNING,
                Optional.empty(), Optional.empty(), 0, List.of(turn), Instant.EPOCH, Optional.empty());
        return new CanonicalSessionState(
                sessionId, CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 1,
                Optional.of(run), List.of(), List.of());
    }
}

