    @Test
    void duplicateCommandReturnsOriginalResultAndJournalRestoresWatermark() {
        var sessionId = new CanonicalSessionState.SessionId("session-1");
        CommandJournal journal = new CommandJournal(sessionId);
        var first = journal.accept("command-1", CommandJournal.utf8("same"), "result-1");
        var duplicate = journal.accept("command-1", CommandJournal.utf8("same"), "result-ignored");
        assertSame(first, duplicate);
        var restored = new CommandJournal(sessionId, journal.watermark().lastAcceptedSeq(), journal.entries());
        assertEquals(2, restored.accept("command-2", CommandJournal.utf8("next"), "result-2").acceptedSeq());
        assertThrows(CommandJournal.CommandPayloadConflictException.class,
                () -> restored.accept("command-1", CommandJournal.utf8("different"), "result-3"));
    }

