    @Test
    void concurrentDuplicateCommandHasOneAcceptedSequence() throws Exception {
        CommandJournal journal = new CommandJournal(new CanonicalSessionState.SessionId("session-1"));
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            var tasks = java.util.stream.IntStream.range(0, 32)
                    .<java.util.concurrent.Callable<Long>>mapToObj(index -> () ->
                            journal.accept("command-1", CommandJournal.utf8("same"), "result-1").acceptedSeq())
                    .toList();
            var results = executor.invokeAll(tasks);
            assertEquals(1, results.stream().map(future -> {
                try { return future.get(); }
                catch (Exception exception) { throw new AssertionError(exception); }
            }).distinct().count());
        }
    }

